using UnityEngine;

namespace Gamekit2D
{
    // Generated by AI
    /// <summary>Creates the forest-care HUD and collectible litter in Zone 1.</summary>
    [RequireComponent(typeof(ForestCareProgress))]
    public sealed class ForestCleanupSceneInstaller : MonoBehaviour
    {
        private const int RequiredItems = 3;
        private static readonly Vector2[] ItemPositions =
        {
            new Vector2(-0.8f, -4.05f),
            new Vector2(2.8f, -3.45f),
            new Vector2(8.1f, -2.85f)
        };

        private void Awake()
        {
            ForestCareProgress progress = GetComponent<ForestCareProgress>();
            progress.Initialize(RequiredItems);

            for (int i = 0; i < RequiredItems; i++)
                CreateLitter(i, progress);
        }

        private void CreateLitter(int index, ForestCareProgress progress)
        {
            string[] names = { "Water Bottle", "Discarded Can", "Forest Paper Waste" };
            GameObject litter = new GameObject(names[index]);
            litter.transform.SetParent(transform, true);
            litter.transform.position = ItemPositions[index];
            litter.transform.localScale = Vector3.one * 0.62f;

            SpriteRenderer renderer = litter.AddComponent<SpriteRenderer>();
            renderer.sprite = CreateLitterSprite(index);
            renderer.sortingOrder = 20;

            CircleCollider2D trigger = litter.AddComponent<CircleCollider2D>();
            trigger.isTrigger = true;
            trigger.radius = 0.7f;

            litter.AddComponent<ForestCleanupCollectible>().Initialize(progress);
        }

        private static Sprite CreateLitterSprite(int kind)
        {
            const int size = 32;
            Texture2D texture = new Texture2D(size, size, TextureFormat.RGBA32, false);
            texture.filterMode = FilterMode.Point;
            texture.wrapMode = TextureWrapMode.Clamp;
            Color clear = new Color(0, 0, 0, 0);
            Color outline = new Color(0.12f, 0.16f, 0.13f, 1);
            Color main = kind == 0 ? new Color(0.28f, 0.75f, 0.64f) :
                         kind == 1 ? new Color(0.82f, 0.48f, 0.19f) :
                                     new Color(0.88f, 0.84f, 0.64f);
            Color highlight = kind == 0 ? new Color(0.66f, 0.94f, 0.82f) :
                              kind == 1 ? new Color(0.96f, 0.76f, 0.37f) :
                                          new Color(0.98f, 0.96f, 0.85f);
            Color[] pixels = new Color[size * size];
            for (int i = 0; i < pixels.Length; i++) pixels[i] = clear;

            if (kind == 0)
            {
                FillPolygon(pixels, new[] { new Vector2Int(10, 2), new Vector2Int(22, 2), new Vector2Int(23, 6), new Vector2Int(21, 10), new Vector2Int(21, 26), new Vector2Int(18, 30), new Vector2Int(14, 30), new Vector2Int(11, 26), new Vector2Int(11, 10), new Vector2Int(9, 6) }, outline);
                FillPolygon(pixels, new[] { new Vector2Int(12, 4), new Vector2Int(20, 4), new Vector2Int(20, 9), new Vector2Int(19, 11), new Vector2Int(19, 25), new Vector2Int(17, 28), new Vector2Int(15, 28), new Vector2Int(13, 25), new Vector2Int(13, 11), new Vector2Int(12, 9) }, main);
                FillRect(pixels, 14, 27, 18, 31, new Color(0.92f, 0.78f, 0.3f, 1));
                FillRect(pixels, 14, 14, 15, 23, highlight);
            }
            else if (kind == 1)
            {
                FillPolygon(pixels, new[] { new Vector2Int(10, 3), new Vector2Int(22, 3), new Vector2Int(24, 6), new Vector2Int(24, 26), new Vector2Int(22, 29), new Vector2Int(10, 29), new Vector2Int(8, 26), new Vector2Int(8, 6) }, outline);
                FillRect(pixels, 10, 6, 22, 26, main);
                FillRect(pixels, 11, 22, 21, 23, highlight);
                FillRect(pixels, 11, 10, 12, 20, new Color(1, 0.86f, 0.58f, 1));
                FillRect(pixels, 9, 26, 23, 27, new Color(0.68f, 0.75f, 0.69f, 1));
                FillRect(pixels, 9, 4, 23, 5, new Color(0.68f, 0.75f, 0.69f, 1));
            }
            else
            {
                FillPolygon(pixels, new[] { new Vector2Int(4, 9), new Vector2Int(10, 5), new Vector2Int(15, 7), new Vector2Int(21, 4), new Vector2Int(28, 10), new Vector2Int(25, 16), new Vector2Int(28, 22), new Vector2Int(21, 27), new Vector2Int(15, 24), new Vector2Int(8, 28), new Vector2Int(4, 21), new Vector2Int(7, 15) }, outline);
                FillPolygon(pixels, new[] { new Vector2Int(7, 10), new Vector2Int(11, 8), new Vector2Int(16, 10), new Vector2Int(21, 7), new Vector2Int(25, 11), new Vector2Int(22, 16), new Vector2Int(25, 21), new Vector2Int(20, 24), new Vector2Int(15, 21), new Vector2Int(9, 24), new Vector2Int(7, 20), new Vector2Int(10, 15) }, main);
                DrawLine(pixels, 11, 10, 19, 22, highlight);
                DrawLine(pixels, 10, 19, 22, 11, new Color(0.72f, 0.67f, 0.47f, 1));
            }

            texture.SetPixels(pixels);
            texture.Apply(false, true);
            return Sprite.Create(texture, new Rect(0, 0, size, size), new Vector2(0.5f, 0.12f), size);
        }

        private static void FillRect(Color[] pixels, int xMin, int yMin, int xMax, int yMax, Color color)
        {
            for (int y = yMin; y <= yMax; y++)
                for (int x = xMin; x <= xMax; x++)
                    pixels[y * 32 + x] = color;
        }

        private static void FillPolygon(Color[] pixels, Vector2Int[] points, Color color)
        {
            for (int y = 0; y < 32; y++)
            for (int x = 0; x < 32; x++)
            {
                bool inside = false;
                for (int i = 0, j = points.Length - 1; i < points.Length; j = i++)
                {
                    Vector2Int a = points[i];
                    Vector2Int b = points[j];
                    if ((a.y > y) != (b.y > y) && x < (b.x - a.x) * (y - a.y) / (float)(b.y - a.y) + a.x)
                        inside = !inside;
                }
                if (inside) pixels[y * 32 + x] = color;
            }
        }

        private static void DrawLine(Color[] pixels, int x0, int y0, int x1, int y1, Color color)
        {
            int steps = Mathf.Max(Mathf.Abs(x1 - x0), Mathf.Abs(y1 - y0));
            for (int step = 0; step <= steps; step++)
            {
                int x = Mathf.RoundToInt(Mathf.Lerp(x0, x1, steps == 0 ? 0 : (float)step / steps));
                int y = Mathf.RoundToInt(Mathf.Lerp(y0, y1, steps == 0 ? 0 : (float)step / steps));
                pixels[y * 32 + x] = color;
            }
        }
    }
}
